   168	// Adds per-round token counts so the hook receives the total across all provider calls in the turn.
   169	function accumulateUsage(
   170	  acc: TurnUsageMetadata | undefined,
   171	  next: UsageMetadata | undefined
   172	): TurnUsageMetadata | undefined {
   173	  if (!acc) return next;
   174	  if (!next) return acc;
   175	  return {
   176	    inputTokens: acc.inputTokens + next.inputTokens,
   177	    outputTokens: acc.outputTokens + next.outputTokens,
   178	    totalTokens: acc.totalTokens + next.totalTokens,
   179	  };
   180	}
