   182	// A negative budget means no tool rounds; a non-finite one, NaN included, falls back to the default rather than never ending.
   183	function normalizeToolRounds(value: number | undefined): number {
   184	  if (value === undefined || !Number.isFinite(value)) return DEFAULT_MAX_TOOL_ROUNDS;
   185	  return Math.max(0, Math.floor(value));
   186	}
   187	
   188	// Gates execution, not the provider call: a round nobody can read is never run, and the call that read the last one already has.
   189	function budgetSpent(round: number, maxToolRounds: number, pendingToolCalls: ToolCall[]): boolean {
   190	  if (round < maxToolRounds) return false;
   191	  log.warn('orchestrator', 'tool budget exhausted', {
   192	    maxToolRounds,
   193	    requestedTools: pendingToolCalls.map(tc => tc.name),
   194	  });
   195	  return true;
   196	}
   197	
   198	// The stop always follows the text: the round's own stop already committed its entry, and a bare text chunk would open one never committed.
   199	async function* closeExhaustedTurn(
   200	  session: ChatSession,
   201	  budget: ToolBudgetInfo,
   202	  hook?: OnToolBudgetExhausted
   203	): AsyncGenerator<MessageChunk, string> {
   204	  const sentence = (hook ? await hook(session, budget) : undefined) ?? '';
   205	  if (sentence !== '') yield {type: 'text', text: sentence};
   206	  yield {type: 'stop', stopReason: TOOL_BUDGET_EXHAUSTED};
   207	  return sentence;
   208	}
   209	
   210	interface RoundOutcome {
   211	  stopReason: string;
   212	  text: string;
   213	  usage?: UsageMetadata;
   214	}
   215	
   216	// `yield*` in the caller evaluates to this return, so the round's totals come back as data.
   217	async function* streamRound(
   218	  provider: AIProvider,
   219	  request: SendMessageParams,
   220	  pendingToolCalls: ToolCall[]
   221	): AsyncGenerator<MessageChunk, RoundOutcome> {
   222	  let stopReason = '';
   223	  let text = '';
   224	  let usage: UsageMetadata | undefined;
   225	
   226	  for await (const chunk of provider.sendMessage(request)) {
   227	    yield chunk;
   228	    collectToolCalls(chunk, pendingToolCalls);
   229	    stopReason = extractStopReason(chunk) ?? stopReason;
   230	    usage = extractUsage(chunk) ?? usage;
   231	    if (chunk.type === 'text') text += chunk.text;
   232	  }
   233	
   234	  return {stopReason, text, usage};
   235	}
   236	
   237	// A changed message is also written back to the session's last user entry.
   238	async function rewriteUserMessage(
   239	  session: ChatSession,
   240	  userMessage: string,
   241	  hook: (session: ChatSession, userMessage: string) => Promise<string>
   242	): Promise<string> {
   243	  const modified = await hook(session, userMessage);
   244	  if (modified === userMessage) return userMessage;
   245	
   246	  updateLastUserContent(session, modified);
   247	  return modified;
   248	}
   249	
   250	function lastUserContent(session: ChatSession): string {
   251	  for (let i = session.entries.length - 1; i >= 0; i--) {
   252	    const entry = session.entries[i];
   253	    if (entry.role === 'user') return entry.content;
   254	  }
   255	  return '';
   256	}
   257	
   258	function updateLastUserContent(session: ChatSession, content: string): void {
   259	  for (let i = session.entries.length - 1; i >= 0; i--) {
   260	    const entry = session.entries[i];
   261	    if (entry.role === 'user') {
   262	      entry.content = content;
   263	      return;
   264	    }
   265	  }
   266	}
