   268	// One runner per round: the policy sees each known call before its executor, and an unknown name keeps the registry's own path.
   269	function toolCallRunner(toolRegistry: ToolRegistry, session: ChatSession, beforeToolCall?: BeforeToolCall) {
   270	  const context: ToolContext = {
   271	    userId: session.userId,
   272	    sessionId: session.sessionId,
   273	    workspaceId: session.workspaceId,
   274	    authHeaders: session.authHeaders,
   275	  };
   276	
   277	  return async (tc: ToolCall): Promise<ToolResponse> => {
   278	    const declined =
   279	      beforeToolCall && toolRegistry.has(tc.name) ? await consultPolicy(beforeToolCall, session, tc) : undefined;
   280	    return declined ?? toolRegistry.execute(tc.name, tc.input, context);

